import * as dagre from "@dagrejs/dagre";

export interface DagreNode {
  id: string;
  label?: string;
  width?: number;
  height?: number;
  class?: string;
  shape?: "rect" | "diamond" | "ellipse";
  /** Nest this node inside the cluster named by another node's id (compound layout). */
  parent?: string;
}

export interface DagreEdge {
  source: string;
  target: string;
  label?: string;
  class?: string;
}

export interface DagreGraphConfig {
  nodes?: DagreNode[];
  edges?: DagreEdge[];
}

export interface DagreLayoutConfig {
  rankdir?: "TB" | "BT" | "LR" | "RL";
  align?: "UL" | "UR" | "DL" | "DR";
  nodesep?: number;
  edgesep?: number;
  ranksep?: number;
  marginx?: number;
  marginy?: number;
  ranker?: "network-simplex" | "tight-tree" | "longest-path";
}

const SVG = "http://www.w3.org/2000/svg";
const NODE_FONT = "12px system-ui, sans-serif";
const EDGE_FONT = "11px system-ui, sans-serif";
const PAD_X = 16;
const PAD_Y = 10;
const MIN_W = 60;
const MIN_H = 32;
const EDGE_SAMPLES = 24; // fixed point count so edge paths interpolate cleanly
const MIN_ZOOM = 0.2;
const MAX_ZOOM = 8;
const PAN_STEP = 60; // control-arrow pan distance, in svg user units
const EDGE_MARGIN = 48; // minimum graph extent kept inside the window when panning/zooming

let measureContext: CanvasRenderingContext2D | null = null;

function measure(text: string, font: string): number {
  measureContext ??= document.createElement("canvas").getContext("2d");
  if (!measureContext) return text.length * 7;
  measureContext.font = font;
  return measureContext.measureText(text).width;
}

// trim to the widest prefix that fits `max` with a trailing ellipsis appended
function ellipsize(text: string, font: string, max: number): string {
  if (measure(text, font) <= max) return text;
  let out = text;
  while (out.length && measure(`${out}…`, font) > max) {
    out = out.slice(0, -1);
  }
  return `${out}…`;
}

type Point = { x: number; y: number };

// resample dagre's polyline to a fixed number of evenly spaced points (by arc length),
// so any two edge paths share structure and interpolate point-for-point
function resample(points: Point[], count: number): Point[] {
  if (points.length === 0) return [];
  if (points.length === 1) return Array(count).fill(points[0]);
  const lengths = [0];
  for (let i = 1; i < points.length; i++) {
    const dx = points[i].x - points[i - 1].x;
    const dy = points[i].y - points[i - 1].y;
    lengths.push(lengths[i - 1] + Math.hypot(dx, dy));
  }
  const total = lengths[lengths.length - 1] || 1;
  const out: Point[] = [];
  let seg = 1;
  for (let i = 0; i < count; i++) {
    const target = (total * i) / (count - 1);
    while (seg < points.length - 1 && lengths[seg] < target) seg++;
    const t =
      (target - lengths[seg - 1]) / (lengths[seg] - lengths[seg - 1] || 1);
    out.push({
      x: points[seg - 1].x + (points[seg].x - points[seg - 1].x) * t,
      y: points[seg - 1].y + (points[seg].y - points[seg - 1].y) * t,
    });
  }
  return out;
}

// a smooth path through resampled points: line to midpoints, quadratic through the
// interior points — the classic rounded polyline, with no d3 dependency
function edgePath(points: Point[]): string {
  if (points.length < 2) return "";
  const parts = [`M ${points[0].x} ${points[0].y}`];
  for (let i = 1; i < points.length - 1; i++) {
    const mid = {
      x: (points[i].x + points[i + 1].x) / 2,
      y: (points[i].y + points[i + 1].y) / 2,
    };
    parts.push(`Q ${points[i].x} ${points[i].y} ${mid.x} ${mid.y}`);
  }
  const last = points[points.length - 1];
  parts.push(`L ${last.x} ${last.y}`);
  return parts.join(" ");
}

function el<K extends keyof SVGElementTagNameMap>(
  tag: K,
  attrs: Record<string, string>,
): SVGElementTagNameMap[K] {
  const node = document.createElementNS(SVG, tag);
  for (const [key, value] of Object.entries(attrs)) {
    node.setAttribute(key, value);
  }
  return node;
}

// dagre routes edges to the rectangular bbox; nodes drawn as inscribed shapes need the
// true boundary, so edge endpoints are re-clipped along the ray toward the neighbor point
function shapeIntersect(
  center: Point,
  half: { w: number; h: number },
  shape: DagreNode["shape"],
  toward: Point,
): Point | null {
  const dx = toward.x - center.x;
  const dy = toward.y - center.y;
  if ((!dx && !dy) || !half.w || !half.h) return null;
  let t = 0;
  if (shape === "diamond")
    t = 1 / (Math.abs(dx) / half.w + Math.abs(dy) / half.h);
  else if (shape === "ellipse") t = 1 / Math.hypot(dx / half.w, dy / half.h);
  else return null;
  return { x: center.x + dx * t, y: center.y + dy * t };
}

function ease(t: number): number {
  return t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2;
}

interface NodeLaid {
  x: number;
  y: number;
  width: number;
  height: number;
}

interface EdgeLaid {
  points: Point[];
  label?: Point;
}

// `<spaday-dagre>` renders a serializable node/edge graph laid out by @dagrejs/dagre as
// light-DOM SVG, so the package stylesheet (and any application CSS) reaches every shape.
// Colors ride the spaday shell's --spa-* tokens with wa-dark/wa-light values, following
// the ecosystem's page-mode convention. Interactivity is what dagre-d3 was liked for:
// wheel zoom (cursor-anchored) + drag pan + double-click reset (`zoomable`), animated
// re-layout with per-element identity preserved across renders (`transition`, ms), and
// CSS hover affordances. `dagre-node-click` bubbles `{id, label, x, y}` and
// `dagre-edge-click` bubbles `{source, target, label, x, y}` — the graph context plus the
// pointer's client coordinates, like the contextmenu events — so spaday's `event_value("id")`
// / `event_value("x")` paths walk the detail; a drag suppresses the trailing click.
// Sizing: the host draws into an absolutely positioned frame, so it contributes no
// intrinsic height — give `<spaday-dagre>` or an ancestor an explicit height. An unsized
// host falls back to the graph's natural height, with a one-time console warning.
class SpadayDagre extends HTMLElement {
  #graph: DagreGraphConfig = {};
  #layout: DagreLayoutConfig = {};
  #zoomable = true;
  #transition = 250;
  #maxLabelWidth: number | null = null;
  #emphasis: string[] = [];
  #focus: string | null = null;
  #rendered = false;
  #svg: SVGSVGElement | null = null;
  #viewport: SVGGElement | null = null;
  #clusterLayer: SVGGElement | null = null;
  #nodeEls = new Map<string, SVGGElement>();
  #edgeEls = new Map<string, SVGGElement>();
  #clusterEls = new Map<string, SVGGElement>();
  #nodeLaid = new Map<string, NodeLaid>();
  #edgeLaid = new Map<string, EdgeLaid>();
  #clusterLaid = new Map<string, NodeLaid>();
  #view = { x: 0, y: 0, k: 1 };
  // the window is the component's own size (1 css px = 1 user unit); the graph's natural
  // extent moves within it via the view transform
  #window = { w: 0, h: 0 };
  #graphSize = { w: 0, h: 0 };
  // the view is automatic (fit-and-centered, re-fitted on every window or graph change) until
  // the user pans or zooms or a node is focused; a reset or `fit()` makes it automatic again.
  // A measured box is never trusted as final — a tab, accordion, or drawer built before it is
  // shown can pass through transient sizes, and a fit against one must not stick.
  #autoFit = true;
  #controls = false;
  #controlsEl: HTMLDivElement | null = null;
  // tracks the host's size: the svg window and the control pad follow it
  #resize =
    typeof ResizeObserver !== "undefined"
      ? new ResizeObserver(() => this.#syncWindow())
      : null;
  #frame = 0;
  #dragged = false;
  #warnedUnsized = false;

  connectedCallback(): void {
    this.style.display ||= "block";
    this.#resize?.observe(this);
    if (!this.#rendered) this.#render();
    else this.#syncWindow(); // rendered while disconnected: adopt the real size now
    this.addEventListener("click", (event) => {
      if (this.#dragged) return; // a pan, not a selection
      const target = event.target as Element;
      const node = target.closest("[data-node-id]");
      // clicks carry the graph context plus the pointer position, mirroring the
      // contextmenu events, so event_value("id")/("x")/("y") paths walk the detail
      const position = { x: event.clientX, y: event.clientY };
      if (node) {
        const id = node.getAttribute("data-node-id") ?? "";
        const config = this.#graph.nodes?.find((n) => n.id === id);
        this.dispatchEvent(
          new CustomEvent("dagre-node-click", {
            detail: { id, label: config?.label ?? id, ...position },
            bubbles: true,
            composed: true,
          }),
        );
        return;
      }
      const edge = target.closest("[data-edge-source]");
      if (edge) {
        this.dispatchEvent(
          new CustomEvent("dagre-edge-click", {
            detail: {
              source: edge.getAttribute("data-edge-source"),
              target: edge.getAttribute("data-edge-target"),
              label: edge.getAttribute("data-edge-label") ?? undefined,
              ...position,
            },
            bubbles: true,
            composed: true,
          }),
        );
      }
    });
    this.addEventListener("contextmenu", (event) => {
      // Right-clicking a node or edge dispatches an enriched contextmenu event carrying the
      // graph context plus the pointer position, and suppresses the native menu over that
      // shape (background right-clicks keep the browser menu). Pairs with spaday's
      // `open_popup(x=event_value("detail.x"), y=event_value("detail.y"), ...)`.
      const target = event.target as Element;
      const node = target.closest("[data-node-id]");
      const edge = node ? null : target.closest("[data-edge-source]");
      if (!node && !edge) return;
      event.preventDefault();
      const position = { x: event.clientX, y: event.clientY };
      if (node) {
        this.dispatchEvent(
          new CustomEvent("dagre-node-contextmenu", {
            detail: { id: node.getAttribute("data-node-id"), ...position },
            bubbles: true,
            composed: true,
          }),
        );
      } else if (edge) {
        this.dispatchEvent(
          new CustomEvent("dagre-edge-contextmenu", {
            detail: {
              source: edge.getAttribute("data-edge-source"),
              target: edge.getAttribute("data-edge-target"),
              label: edge.getAttribute("data-edge-label") ?? undefined,
              ...position,
            },
            bubbles: true,
            composed: true,
          }),
        );
      }
    });
  }

  set graph(value: DagreGraphConfig | null) {
    this.#graph = value ?? {};
    this.#render();
  }
  get graph(): DagreGraphConfig {
    return this.#graph;
  }

  set layout(value: DagreLayoutConfig | null) {
    this.#layout = value ?? {};
    this.#autoFit = true; // a new layout re-fits and re-centers the view
    this.#render();
  }
  get layout(): DagreLayoutConfig {
    return this.#layout;
  }

  /** Wheel zoom, drag pan, and double-click reset (default true). */
  set zoomable(value: boolean) {
    this.#zoomable = value !== false;
  }
  get zoomable(): boolean {
    return this.#zoomable;
  }

  /** Overlay pan arrows and a center reset control on the graph (default false). */
  set controls(value: boolean) {
    this.#controls = Boolean(value);
    this.#syncControls();
  }
  get controls(): boolean {
    return this.#controls;
  }

  /** Node ids wearing the `.emphasis` class (a single id string is accepted; null clears).
   * Toggled by class reconciliation against the rendered node groups — no re-layout, and
   * the `graph` prop is untouched — and re-applied after every render so it survives
   * graph/layout changes. A node whose config `class` includes "emphasis" keeps it. */
  set emphasis(value: string[] | string | null) {
    this.#emphasis =
      value == null
        ? []
        : Array.isArray(value)
          ? value.map(String)
          : [String(value)];
    this.#applyEmphasis();
  }
  get emphasis(): string[] {
    return this.#emphasis;
  }

  /** Bindable spelling of `focusNode`: setting a node id pans/zooms it to the window
   * center. `focusNode(id)` is the primary API; this property just calls it on set.
   * Defined imperatively because it deliberately shadows `HTMLElement.focus()` (the graph
   * never takes keyboard focus), which TypeScript rejects as an accessor override. */
  static {
    Object.defineProperty(SpadayDagre.prototype, "focus", {
      configurable: true,
      get(this: SpadayDagre): string | null {
        return this.#focus;
      },
      set(this: SpadayDagre, value: string | null) {
        this.#focus = value || null;
        if (this.#focus) this.focusNode(this.#focus);
      },
    });
  }

  /** Pan — and, when the current zoom is below 1:1 or the node overflows the window, zoom
   * to a comfortable level — so the node (or cluster) `id` is centered in the window. */
  focusNode(id: string): void {
    const laid = this.#nodeLaid.get(id) ?? this.#clusterLaid.get(id);
    const { w, h } = this.#window;
    if (!laid || !w || !h) return;
    // comfortable zoom: keep the current level when it is already >= 1:1 and the node
    // fits; clamp up to 1 when zoomed further out, down to fitting when zoomed too far in
    const fit = Math.min(
      w / (laid.width + EDGE_MARGIN),
      h / (laid.height + EDGE_MARGIN),
    );
    const k = Math.min(
      Math.max(this.#view.k, 1),
      Math.max(fit, MIN_ZOOM),
      MAX_ZOOM,
    );
    this.#view = { x: w / 2 - laid.x * k, y: h / 2 - laid.y * k, k };
    this.#autoFit = false;
    this.#applyView();
  }

  /** Fit-and-center the whole graph in the window and resume automatic fitting on later
   * size or graph changes (the double-click / "Reset view" behavior, for hosts to drive:
   * `Invoke(by_id("graph"), "fit")`). */
  fit(): void {
    this.#resetView();
  }

  // pure class reconciliation: no layout, no render, no touching the `graph` prop
  #applyEmphasis(): void {
    const ids = new Set(this.#emphasis);
    // config-driven emphasis (a node class containing "emphasis") is never stripped
    const own = new Set(
      (this.#graph.nodes ?? [])
        .filter((node) => (node.class ?? "").split(/\s+/).includes("emphasis"))
        .map((node) => node.id),
    );
    for (const [id, group] of this.#nodeEls) {
      group.classList.toggle("emphasis", ids.has(id) || own.has(id));
    }
  }

  /** Cap on a node label's measured width in px: wider labels stop widening the node and
   * render ellipsized, with the full label as a native tooltip. Unset keeps natural widths. */
  set maxLabelWidth(value: number | null) {
    this.#maxLabelWidth = Number(value) || null;
    if (this.#rendered) this.#render();
  }
  get maxLabelWidth(): number | null {
    return this.#maxLabelWidth;
  }

  /** Re-layout transition duration in ms; 0 disables (also disabled by reduced motion).
   * (Named `transition` because `animate` is the Web Animations API's Element.animate.) */
  set transition(value: number | null) {
    this.#transition = Number(value) || 0;
  }
  get transition(): number {
    return this.#transition;
  }

  /** The current pan/zoom, for tests and imperative hosts. */
  get view(): { x: number; y: number; k: number } {
    return { ...this.#view };
  }

  #duration(): number {
    if (!this.#transition) return 0;
    if (
      typeof matchMedia !== "undefined" &&
      matchMedia("(prefers-reduced-motion: reduce)").matches
    )
      return 0;
    return this.#transition;
  }

  #ensureSvg(): { svg: SVGSVGElement; viewport: SVGGElement } {
    if (this.#svg && this.#viewport)
      return { svg: this.#svg, viewport: this.#viewport };
    const svg = el("svg", { role: "img" });
    const defs = el("defs", {});
    const marker = el("marker", {
      id: "spaday-dagre-arrow",
      class: "spaday-dagre-arrow",
      viewBox: "0 0 10 10",
      refX: "9",
      refY: "5",
      markerWidth: "7",
      markerHeight: "7",
      orient: "auto-start-reverse",
    });
    marker.append(el("path", { d: "M 0 0 L 10 5 L 0 10 z" }));
    defs.append(marker);
    const viewport = el("g", { class: "spaday-dagre-viewport" });
    // clusters live in a layer that stays the viewport's first child, so they always
    // paint behind the edge and node groups appended after it
    const clusters = el("g", { class: "spaday-dagre-clusters" });
    viewport.append(clusters);
    svg.append(defs, viewport);
    this.#svg = svg;
    this.#viewport = viewport;
    this.#clusterLayer = clusters;
    this.#wireZoom(svg);
    // the frame fills the host — the component's size dictates it, and the svg scales into it
    // (max-width/height resolve against the frame's definite size) — with the graph centered
    const frame = document.createElement("div");
    frame.className = "spaday-dagre-frame";
    frame.append(svg);
    this.replaceChildren(frame);
    this.#syncControls();
    return { svg, viewport };
  }

  // Size the svg window to the component: the graph pans across the component's full
  // extents, not just its own natural box. An absolutely positioned frame contributes no
  // auto height, so an unsized host defaults to the graph's natural height.
  #syncWindow(): void {
    const svg = this.#svg;
    if (!svg) return;
    // the natural-height fallback must never override an author-sized host (min-height
    // beats height), so re-measure without it each time and reapply only if still unsized
    if (this.style.minHeight) this.style.minHeight = "";
    if (!this.clientHeight && this.#graphSize.h) {
      // a rendered host resolving to zero height is almost always a sizing bug: the
      // frame is absolutely positioned, so the host contributes no intrinsic height
      if (!this.#warnedUnsized && this.isConnected && this.clientWidth > 0) {
        this.#warnedUnsized = true;
        console.warn(
          "<spaday-dagre> resolved to zero height and fell back to the graph's natural height; give <spaday-dagre> or an ancestor an explicit height.",
        );
      }
      this.style.minHeight = `${this.#graphSize.h}px`;
    }
    const w = this.clientWidth || this.#graphSize.w;
    const h = this.clientHeight || this.#graphSize.h;
    if (!w || !h) return;
    this.#window = { w, h };
    svg.setAttribute("viewBox", `0 0 ${w} ${h}`);
    svg.setAttribute("width", String(w));
    svg.setAttribute("height", String(h));
    if (this.#autoFit && this.#graphSize.w) this.#resetView();
    else this.#applyView(); // the user's view survives a resize, clamped into the new window
    this.#placeControls();
  }

  #applyView(): void {
    // clamp the pan so at least EDGE_MARGIN of the graph stays inside the window — a drag or
    // zoom can never strand the diagram entirely off-screen
    const { w, h } = this.#window;
    const { w: gw, h: gh } = this.#graphSize;
    const k = this.#view.k;
    if (w && h && gw && gh) {
      const mx = Math.min(EDGE_MARGIN, w / 2, (gw * k) / 2);
      const my = Math.min(EDGE_MARGIN, h / 2, (gh * k) / 2);
      this.#view.x = Math.max(mx - gw * k, Math.min(this.#view.x, w - mx));
      this.#view.y = Math.max(my - gh * k, Math.min(this.#view.y, h - my));
    }
    this.#viewport?.setAttribute(
      "transform",
      `translate(${this.#view.x} ${this.#view.y}) scale(${this.#view.k})`,
    );
  }

  #pan(dx: number, dy: number): void {
    this.#autoFit = false;
    this.#view.x += dx;
    this.#view.y += dy;
    this.#applyView();
  }

  // Fit-and-center: the whole graph visible, centered in the window (also the initial view),
  // and automatic fitting resumes.
  #resetView(): void {
    this.#autoFit = true;
    const { w, h } = this.#window;
    const { w: gw, h: gh } = this.#graphSize;
    const k = Math.max(MIN_ZOOM, Math.min(1, w / (gw || 1), h / (gh || 1)));
    this.#view = { x: (w - gw * k) / 2, y: (h - gh * k) / 2, k };
    this.#applyView();
  }

  // Optional on-graph controls (GitHub's mermaid style): a D-pad whose arrows nudge the diagram
  // in the arrow's direction, around a center circle that resets pan/zoom.
  #syncControls(): void {
    if (!this.#controls || !this.#svg) {
      this.#controlsEl?.remove();
      this.#controlsEl = null;
      return;
    }
    if (!this.#controlsEl) {
      const pad = document.createElement("div");
      pad.className = "spaday-dagre-controls";
      const button = (
        label: string,
        title: string,
        area: string,
        act: () => void,
      ) => {
        const b = document.createElement("button");
        b.type = "button";
        b.title = title;
        b.textContent = label;
        b.style.gridArea = area;
        b.className = `spaday-dagre-control-${area}`;
        b.addEventListener("click", act);
        pad.append(b);
      };
      button("\u2191", "Pan up", "up", () => this.#pan(0, -PAN_STEP));
      button("\u2190", "Pan left", "left", () => this.#pan(-PAN_STEP, 0));
      button("\u25cb", "Reset view", "reset", () => this.#resetView());
      button("\u2192", "Pan right", "right", () => this.#pan(PAN_STEP, 0));
      button("\u2193", "Pan down", "down", () => this.#pan(0, PAN_STEP));
      this.#controlsEl = pad;
    }
    const frame = this.#svg.parentElement;
    if (frame && this.#controlsEl.parentNode !== frame)
      frame.append(this.#controlsEl);
    this.#placeControls();
  }

  // Beside the graph's bottom-right corner when there is room, clamped inside the frame
  // (over the corner) when there is not. Re-run by the ResizeObserver on any host or
  // graph size change.
  #placeControls(): void {
    const pad = this.#controlsEl;
    const svg = this.#svg;
    const frame = svg?.parentElement;
    if (!pad || !svg || !frame) return;
    const fr = frame.getBoundingClientRect();
    const sr = svg.getBoundingClientRect();
    const gap = 10;
    const margin = 4;
    const padW = pad.offsetWidth || 84;
    const padH = pad.offsetHeight || 84;
    let left = sr.right - fr.left + gap;
    if (left + padW > fr.width - margin)
      left = Math.max(margin, fr.width - padW - margin);
    let top = sr.bottom - fr.top - padH;
    top = Math.min(
      Math.max(margin, top),
      Math.max(margin, fr.height - padH - margin),
    );
    pad.style.left = `${left}px`;
    pad.style.top = `${top}px`;
  }

  // client pixel -> svg user units (the svg may be shrunk by max-width: 100%)
  #toUser(svg: SVGSVGElement, clientX: number, clientY: number): Point {
    const rect = svg.getBoundingClientRect();
    const scale = rect.width
      ? Number(svg.getAttribute("width") || rect.width) / rect.width
      : 1;
    return {
      x: (clientX - rect.left) * scale,
      y: (clientY - rect.top) * scale,
    };
  }

  #wireZoom(svg: SVGSVGElement): void {
    svg.addEventListener(
      "wheel",
      (event) => {
        if (!this.#zoomable) return;
        event.preventDefault();
        const cursor = this.#toUser(svg, event.clientX, event.clientY);
        const k = Math.min(
          MAX_ZOOM,
          Math.max(MIN_ZOOM, this.#view.k * Math.exp(-event.deltaY * 0.002)),
        );
        // keep the point under the cursor fixed while the scale changes
        this.#view.x =
          cursor.x - ((cursor.x - this.#view.x) / this.#view.k) * k;
        this.#view.y =
          cursor.y - ((cursor.y - this.#view.y) / this.#view.k) * k;
        this.#view.k = k;
        this.#autoFit = false;
        this.#applyView();
      },
      { passive: false },
    );
    let panning: Point | null = null;
    svg.addEventListener("pointerdown", (event) => {
      if (!this.#zoomable || event.button !== 0) return;
      panning = this.#toUser(svg, event.clientX, event.clientY);
      this.#dragged = false;
    });
    svg.addEventListener("pointermove", (event) => {
      if (!panning) return;
      const at = this.#toUser(svg, event.clientX, event.clientY);
      const dx = at.x - panning.x;
      const dy = at.y - panning.y;
      if (!this.#dragged && Math.hypot(dx, dy) < 3) return;
      if (!this.#dragged) {
        // capture only once a real drag starts — capturing on pointerdown would
        // retarget the trailing click to the svg and break node/edge selection
        svg.setPointerCapture(event.pointerId);
      }
      this.#dragged = true;
      this.#autoFit = false;
      this.#view.x += dx;
      this.#view.y += dy;
      panning = at;
      this.#applyView();
    });
    const stop = () => {
      panning = null;
      // let the click handler read #dragged for this gesture, then clear it
      setTimeout(() => {
        this.#dragged = false;
      }, 0);
    };
    svg.addEventListener("pointerup", stop);
    svg.addEventListener("pointercancel", stop);
    svg.addEventListener("dblclick", () => {
      if (!this.#zoomable) return;
      this.#resetView();
    });
  }

  #nodeShape(group: SVGGElement, laid: NodeLaid): void {
    const shape = group.querySelector("rect, ellipse, polygon");
    const text = group.querySelector("text");
    if (!shape || !text) return;
    const { x, y, width: w, height: h } = laid;
    if (shape.tagName === "rect") {
      shape.setAttribute("x", String(x - w / 2));
      shape.setAttribute("y", String(y - h / 2));
      shape.setAttribute("width", String(w));
      shape.setAttribute("height", String(h));
    } else if (shape.tagName === "ellipse") {
      shape.setAttribute("cx", String(x));
      shape.setAttribute("cy", String(y));
      shape.setAttribute("rx", String(w / 2));
      shape.setAttribute("ry", String(h / 2));
    } else {
      shape.setAttribute(
        "points",
        `${x},${y - h / 2} ${x + w / 2},${y} ${x},${y + h / 2} ${x - w / 2},${y}`,
      );
    }
    text.setAttribute("x", String(x));
    text.setAttribute("y", String(y));
  }

  #clusterShape(group: SVGGElement, laid: NodeLaid): void {
    const rect = group.querySelector("rect");
    const text = group.querySelector("text");
    if (!rect || !text) return;
    const { x, y, width: w, height: h } = laid;
    rect.setAttribute("x", String(x - w / 2));
    rect.setAttribute("y", String(y - h / 2));
    rect.setAttribute("width", String(w));
    rect.setAttribute("height", String(h));
    // the label sits centered along the cluster's top edge
    text.setAttribute("x", String(x));
    text.setAttribute("y", String(y - h / 2 + 6));
  }

  #edgeShape(group: SVGGElement, laid: EdgeLaid): void {
    for (const path of group.querySelectorAll("path")) {
      path.setAttribute("d", edgePath(laid.points));
    }
    const text = group.querySelector("text");
    if (text && laid.label) {
      text.setAttribute("x", String(laid.label.x));
      text.setAttribute("y", String(laid.label.y));
    }
  }

  #render(): void {
    if (typeof document === "undefined") return;
    this.#rendered = true;
    const nodes = this.#graph.nodes ?? [];
    const edges = this.#graph.edges ?? [];
    // ids referenced as a `parent` are clusters: dagre computes their geometry during
    // compound layout, and they render as rounded containers behind their children.
    // Graphs without parents keep the flat, non-compound path exactly as before.
    const clusterIds = new Set(
      nodes
        .map((node) => node.parent)
        .filter((parent): parent is string => parent != null),
    );
    const compound = clusterIds.size > 0;
    const g = new dagre.graphlib.Graph({ multigraph: true, compound });
    g.setGraph({ marginx: 8, marginy: 8, ...this.#layout });
    g.setDefaultEdgeLabel(() => ({}));
    const cap = this.#maxLabelWidth;
    for (const node of nodes) {
      if (clusterIds.has(node.id)) continue; // a cluster: dagre sizes it during layout
      const label = node.label ?? node.id;
      const measured = measure(label, NODE_FONT);
      // Diamonds inflate by sqrt(2) per axis (as in dagre-d3) so the label box
      // still fits inside the rotated square.
      const inflate = node.shape === "diamond" ? Math.SQRT2 : 1;
      g.setNode(node.id, {
        width:
          (node.width ??
            Math.max(
              MIN_W,
              (cap ? Math.min(measured, cap) : measured) + PAD_X * 2,
            )) * inflate,
        height: (node.height ?? MIN_H + PAD_Y) * inflate,
      });
    }
    if (compound) {
      for (const id of clusterIds) {
        if (!g.hasNode(id)) g.setNode(id, {});
      }
      for (const node of nodes) {
        if (node.parent != null) g.setParent(node.id, node.parent);
      }
    }
    const shapeById = new Map(nodes.map((node) => [node.id, node.shape]));
    const edgeKey = (edge: DagreEdge) => `${edge.source} ${edge.target}`;
    for (const edge of edges) {
      const sized = edge.label
        ? {
            width: measure(edge.label, EDGE_FONT) + 8,
            height: 16,
            labelpos: "c",
          }
        : {};
      g.setEdge(edge.source, edge.target, sized, edgeKey(edge));
    }
    dagre.layout(g);

    const { viewport } = this.#ensureSvg();
    const { width = 0, height = 0 } = g.graph();
    // an empty graph lays out with -Infinity extents; treat it as size zero so no fit
    // or natural-height fallback ever runs against garbage numbers
    this.#graphSize = {
      w: Number.isFinite(width) ? Math.ceil(width) : 0,
      h: Number.isFinite(height) ? Math.ceil(height) : 0,
    };
    this.#syncWindow();

    cancelAnimationFrame(this.#frame);
    const duration = this.#duration();
    const steps: ((t: number) => void)[] = [];
    const nextNodeLaid = new Map<string, NodeLaid>();
    const nextEdgeLaid = new Map<string, EdgeLaid>();
    const seenNodes = new Set<string>();
    const seenEdges = new Set<string>();

    for (const edge of edges) {
      const key = edgeKey(edge);
      const laid = g.edge(edge.source, edge.target, key);
      if (!laid) continue;
      seenEdges.add(key);
      const pts = [...(laid.points ?? [])];
      const clip = (id: string, end: number, ref: number) => {
        const shape = shapeById.get(id);
        if (shape !== "diamond" && shape !== "ellipse") return;
        const n = g.node(id);
        if (!n || pts.length < 2) return;
        const hit = shapeIntersect(
          { x: n.x, y: n.y },
          { w: n.width / 2, h: n.height / 2 },
          shape,
          pts[ref],
        );
        if (hit) pts[end] = hit;
      };
      clip(edge.source, 0, 1);
      clip(edge.target, pts.length - 1, pts.length - 2);
      const target: EdgeLaid = {
        points: resample(pts, EDGE_SAMPLES),
        label:
          edge.label && laid.x !== undefined && laid.y !== undefined
            ? { x: laid.x, y: laid.y }
            : undefined,
      };
      nextEdgeLaid.set(key, target);
      let group = this.#edgeEls.get(key);
      if (!group) {
        group = el("g", {
          "data-edge-source": edge.source,
          "data-edge-target": edge.target,
        });
        // hovering an edge lights up both endpoint nodes along with the line
        const endpoints = () => [
          this.#nodeEls.get(edge.source),
          this.#nodeEls.get(edge.target),
        ];
        group.addEventListener("pointerenter", () => {
          for (const node of endpoints())
            node?.classList.add("spaday-dagre-connected");
        });
        group.addEventListener("pointerleave", () => {
          for (const node of endpoints())
            node?.classList.remove("spaday-dagre-connected");
        });
        // a wide transparent twin of the visible path, so thin edges are hoverable
        group.append(
          el("path", { class: "spaday-dagre-edge-hit" }),
          el("path", {
            class: "spaday-dagre-edge-line",
            "marker-end": "url(#spaday-dagre-arrow)",
          }),
        );
        if (target.label) {
          group.append(
            el("text", {
              class: "spaday-dagre-edge-label",
              "text-anchor": "middle",
              "dominant-baseline": "middle",
            }),
          );
        }
        viewport.append(group);
        this.#edgeEls.set(key, group);
        this.#edgeShape(group, target);
      }
      group.setAttribute(
        "class",
        `spaday-dagre-edge ${edge.class ?? ""}`.trim(),
      );
      if (edge.label) group.setAttribute("data-edge-label", edge.label);
      else group.removeAttribute("data-edge-label");
      const text = group.querySelector("text");
      if (text) text.textContent = edge.label ?? "";
      const from = this.#edgeLaid.get(key);
      if (!from || !duration) {
        this.#edgeShape(group, target);
      } else {
        const grp = group;
        steps.push((t) => {
          this.#edgeShape(grp, {
            points: target.points.map((p, i) => ({
              x: from.points[i].x + (p.x - from.points[i].x) * t,
              y: from.points[i].y + (p.y - from.points[i].y) * t,
            })),
            label:
              target.label && from.label
                ? {
                    x: from.label.x + (target.label.x - from.label.x) * t,
                    y: from.label.y + (target.label.y - from.label.y) * t,
                  }
                : target.label,
          });
        });
      }
    }

    for (const node of nodes) {
      if (clusterIds.has(node.id)) continue; // drawn by the cluster pass below
      const laid = g.node(node.id);
      if (!laid) continue;
      seenNodes.add(node.id);
      const target: NodeLaid = {
        x: laid.x,
        y: laid.y,
        width: laid.width,
        height: laid.height,
      };
      nextNodeLaid.set(node.id, target);
      const tag =
        node.shape === "diamond"
          ? "polygon"
          : node.shape === "ellipse"
            ? "ellipse"
            : "rect";
      let group = this.#nodeEls.get(node.id);
      if (!group) {
        group = el("g", { "data-node-id": node.id });
        group.append(
          el(tag, tag === "rect" ? { rx: "6" } : {}),
          el("text", {
            "text-anchor": "middle",
            "dominant-baseline": "middle",
          }),
        );
        viewport.append(group);
        this.#nodeEls.set(node.id, group);
        this.#nodeShape(group, target);
      } else {
        const shape = group.querySelector("rect, ellipse, polygon");
        if (shape && shape.tagName !== tag) {
          shape.replaceWith(el(tag, tag === "rect" ? { rx: "6" } : {}));
        }
      }
      group.setAttribute(
        "class",
        `spaday-dagre-node ${node.class ?? ""}`.trim(),
      );
      const full = node.label ?? node.id;
      const shown = cap ? ellipsize(full, NODE_FONT, cap) : full;
      const label = group.querySelector("text");
      if (label) label.textContent = shown;
      // an ellipsized label keeps the full text reachable as a native tooltip
      let title = group.querySelector<SVGTitleElement>("title");
      if (shown !== full) {
        if (!title) {
          title = el("title", {});
          group.prepend(title);
        }
        title.textContent = full;
      } else {
        title?.remove();
      }
      const from = this.#nodeLaid.get(node.id);
      if (!from || !duration) {
        this.#nodeShape(group, target);
      } else {
        const grp = group;
        steps.push((t) => {
          this.#nodeShape(grp, {
            x: from.x + (target.x - from.x) * t,
            y: from.y + (target.y - from.y) * t,
            width: from.width + (target.width - from.width) * t,
            height: from.height + (target.height - from.height) * t,
          });
        });
      }
    }

    // Cluster pass: keyed like nodes (stable identity in #clusterEls), geometry straight
    // from dagre's compound layout, ordered outermost-first so nesting stacks correctly.
    const nextClusterLaid = new Map<string, NodeLaid>();
    const seenClusters = new Set<string>();
    const layer = this.#clusterLayer;
    const depth = (id: string): number => {
      let d = 0;
      for (let p = g.parent(id); p != null; p = g.parent(p)) d++;
      return d;
    };
    const clusterOrder = compound
      ? [...clusterIds].sort((a, b) => depth(a) - depth(b))
      : [];
    for (const id of clusterOrder) {
      const laid = g.node(id);
      if (!laid || !layer) continue;
      seenClusters.add(id);
      const target: NodeLaid = {
        x: laid.x,
        y: laid.y,
        width: laid.width,
        height: laid.height,
      };
      nextClusterLaid.set(id, target);
      const config = nodes.find((node) => node.id === id);
      let group = this.#clusterEls.get(id);
      if (!group) {
        // data-node-id makes clusters click/contextmenu targets with the node detail shape
        group = el("g", { "data-node-id": id });
        group.append(
          el("rect", { rx: "8" }),
          el("text", {
            "text-anchor": "middle",
            "dominant-baseline": "hanging",
          }),
        );
        this.#clusterEls.set(id, group);
        this.#clusterShape(group, target);
      }
      layer.append(group); // (re)append in outer-first order: parents behind children
      group.setAttribute(
        "class",
        `spaday-dagre-cluster ${config?.class ?? ""}`.trim(),
      );
      const text = group.querySelector("text");
      if (text) text.textContent = config?.label ?? id;
      const from = this.#clusterLaid.get(id);
      if (!from || !duration) {
        this.#clusterShape(group, target);
      } else {
        const grp = group;
        steps.push((t) => {
          this.#clusterShape(grp, {
            x: from.x + (target.x - from.x) * t,
            y: from.y + (target.y - from.y) * t,
            width: from.width + (target.width - from.width) * t,
            height: from.height + (target.height - from.height) * t,
          });
        });
      }
    }

    for (const [id, group] of this.#nodeEls) {
      if (!seenNodes.has(id)) {
        group.remove();
        this.#nodeEls.delete(id);
      }
    }
    for (const [id, group] of this.#clusterEls) {
      if (!seenClusters.has(id)) {
        group.remove();
        this.#clusterEls.delete(id);
      }
    }
    for (const [key, group] of this.#edgeEls) {
      if (!seenEdges.has(key)) {
        group.remove();
        this.#edgeEls.delete(key);
      }
    }
    this.#nodeLaid = nextNodeLaid;
    this.#edgeLaid = nextEdgeLaid;
    this.#clusterLaid = nextClusterLaid;
    this.#applyEmphasis(); // re-applied so emphasis survives graph/layout changes

    if (steps.length && duration) {
      const start = performance.now();
      const tick = (now: number) => {
        const t = ease(Math.min(1, (now - start) / duration));
        for (const step of steps) step(t);
        if (t < 1) this.#frame = requestAnimationFrame(tick);
      };
      this.#frame = requestAnimationFrame(tick);
    }
  }
}

if (
  typeof customElements !== "undefined" &&
  !customElements.get("spaday-dagre")
) {
  customElements.define("spaday-dagre", SpadayDagre);
}

export { SpadayDagre };
